// Generated by vibes-espmatter – system status and reboot endpoints.
#include "espm_web.h"
#include "espm_config.h"

#include <esp_app_desc.h>
#include <esp_chip_info.h>
#include <esp_flash.h>
#include <esp_image_format.h>
#include <esp_heap_caps.h>
#include <esp_idf_version.h>
#include <esp_log.h>
#include <esp_ota_ops.h>
#include <esp_system.h>
#include <esp_timer.h>
#include <freertos/FreeRTOS.h>
#include <freertos/task.h>
#include <nvs.h>

static const char *TAG = "mesp_system";

static const char *reset_reason_str(esp_reset_reason_t r)
{
    switch (r) {
    case ESP_RST_POWERON: return "power-on";
    case ESP_RST_SW: return "software";
    case ESP_RST_PANIC: return "panic";
    case ESP_RST_INT_WDT: return "interrupt watchdog";
    case ESP_RST_TASK_WDT: return "task watchdog";
    case ESP_RST_WDT: return "watchdog";
    case ESP_RST_DEEPSLEEP: return "deep sleep";
    case ESP_RST_BROWNOUT: return "brownout";
    default: return "other";
    }
}

static esp_err_t status_handler(httpd_req_t *req)
{
    if (!mesp_web_authorized(req)) return ESP_OK;
    const esp_app_desc_t *app = esp_app_get_description();
    esp_chip_info_t chip;
    esp_chip_info(&chip);

    Json j;
    j.obj();
    j.key("name").str(MESP_DEVICE_NAME);
    j.key("deviceType").str(MESP_DEVICE_TYPE);
    j.key("firmware").str(app->version);
    j.key("buildId").str(MESP_BUILD_ID);
    j.key("compiled").str(std::string(app->date) + " " + app->time);
    j.key("idf").str(esp_get_idf_version());
    j.key("chip").str(CONFIG_IDF_TARGET);
    j.key("chipRevision").num(chip.revision);
    j.key("cores").num(chip.cores);
    j.key("uptime").num(esp_timer_get_time() / 1000000);
    j.key("resetReason").str(reset_reason_str(esp_reset_reason()));
    j.key("heapFree").num(heap_caps_get_free_size(MALLOC_CAP_INTERNAL));
    j.key("heapMin").num(heap_caps_get_minimum_free_size(MALLOC_CAP_INTERNAL));
    j.key("psramFree").num(heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
    const esp_partition_t *running = esp_ota_get_running_partition();
    j.key("partition").str(running ? running->label : "?");

    // Flash: chip size, the running app image vs. its partition, NVS entries.
    j.key("flash").obj();
    uint32_t flash_size = 0;
    if (esp_flash_get_size(nullptr, &flash_size) == ESP_OK) j.key("size").unum(flash_size);
    const esp_partition_t *app_part = esp_ota_get_running_partition();
    if (app_part) {
        j.key("appPartition").unum(app_part->size);
        esp_partition_pos_t pos = {app_part->address, app_part->size};
        esp_image_metadata_t meta = {};
        if (esp_image_get_metadata(&pos, &meta) == ESP_OK) j.key("app").unum(meta.image_len);
    }
    nvs_stats_t nvs;
    if (nvs_get_stats(nullptr, &nvs) == ESP_OK) {
        j.key("nvsUsed").unum(nvs.used_entries).key("nvsTotal").unum(nvs.total_entries);
    }
    j.end_obj();

    j.end_obj();
    return mesp_web_send_json(req, j.out());
}

static void reboot_task(void *)
{
    vTaskDelay(pdMS_TO_TICKS(500));
    esp_restart();
}

void mesp_restart_soon()
{
    xTaskCreate(reboot_task, "reboot", 2048, nullptr, 5, nullptr);
}

static esp_err_t reboot_handler(httpd_req_t *req)
{
    if (!mesp_web_authorized(req)) return ESP_OK;
    mesp_restart_soon();
    return mesp_web_send_json(req, "{\"ok\":true}");
}

void mesp_system_register_web()
{
    mesp_web_add("/api/status", HTTP_GET, status_handler);
    mesp_web_add("/api/reboot", HTTP_POST, reboot_handler);
}
